import { user, useUserName } from "@app/model";
import { useProxyWatch, useTranslation, useWatchUpdates } from "@fanfanlo";
import { Box, Stack } from "@mui/material";
import { useEffect, useState } from "react";

export function UserInfoSummary(){
    const {t} = useTranslation('homepage/components/user/user-info-summary/content')
    const [token] = useProxyWatch(user, 'data.storeData.user_token', user.data.storeData.user_token);
    const [name] = useUserName()

    if(!name){
        console.log('user logging ')
    }

    // 不能在Hook调用后有条件性返回，改为在JSX中处理条件渲染
    return(
        <>
            {token && (
                <Box>
                    <Stack direction={"row"} spacing={1}>
                        {name && <><Box>{t('UserInfoSummary.user')}</Box>

                        <Box>{name}</Box></>}
                        </Stack></Box>
            )}
        </>
    )
}