import { user } from "@app/model";
import { useProxyWatch, useTranslation } from "@fanfanlo";
import { Box, Button } from "@mui/material";
import { useRouter } from "next/router";


export function AccountRemoveButton() {
  const { t } = useTranslation('homepage/components/page/account/remove/content');
  const router = useRouter();
  function onClick(){
    router.push('/account/remove');
  }
  return (<>
  <Button
    onClick={onClick}
    data-testid="AccountRemoveButton__removeButton__01JFQX8K9X"
    data-test-comment="账户删除按钮，点击后导航到账户删除页面"
  >
    {t('AccountRemoveButton.name')}
  </Button>
  </>)
}

export function AccountRemoveButtonBox(){
    const [userToken] = useProxyWatch(user, 'data.storeData.user_token', user.data.storeData.user_token)
    
    if(!userToken){
        return(<></>)}
    return(
        <Box>
            <AccountRemoveButton />
        </Box>
    )
}